<section class="admin-panel"><h2><?= e(CmsRules::TYPES[$type]) ?></h2><div class="cms-records"><?php foreach(array_slice($rows,0,25) as $row):?><a href="/admin/cms?type=<?= e($type) ?>&amp;id=<?= e($row['id']) ?>"><strong><?= e($row['title']) ?></strong><span><?= e($row['slug']) ?> · <?= e($row['status']) ?> · Revisión <?= e($row['lock_version']) ?></span></a><?php endforeach?><?php if(!$rows):?><p>Aún no hay contenido de este tipo.</p><?php endif?></div><nav class="cms-tabs" aria-label="Paginación"><?php if($offset):?><a href="/admin/cms?type=<?= e($type) ?>&amp;offset=<?= e(max(0,$offset-25)) ?>">Anterior</a><?php endif?><?php if(count($rows)>25):?><a href="/admin/cms?type=<?= e($type) ?>&amp;offset=<?= e($offset+25) ?>">Siguiente</a><?php endif?></nav></section>
<?php if($canEdit):?><form class="admin-panel admin-form" method="post" action="/admin/cms/save?type=<?= e($type) ?><?= $selected?'&amp;id='.e($selected['id']):'' ?>"><h2><?= $selected?'Editar contenido':'Nuevo contenido' ?></h2><p>El texto se publica como texto; no admite HTML. Usa “home” como identificador del bloque principal de Home.</p><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($v('id')) ?>"><input type="hidden" name="lock_version" value="<?= e($v('lock_version')) ?>"><input type="hidden" name="operation_key" value="<?= e($v('operation_key')?:bin2hex(random_bytes(24))) ?>">
<div class="admin-form-grid"><?php foreach(['slug'=>['Identificador para URL',120],'title'=>['Título',180],'seo_title'=>['Título SEO',180],'seo_description'=>['Descripción SEO',300]] as $key=>[$label,$max]):?><label class="admin-field"><span><?= e($label) ?></span><input name="<?= e($key) ?>" maxlength="<?= e($max) ?>" value="<?= e($v($key)) ?>" <?= in_array($key,['slug','title'],true)?'required':'' ?>></label><?php endforeach?>
