<label class="admin-field"><span>Imagen</span><select name="media_id"><option value="">Sin imagen</option><?php foreach($media as $m):?><option value="<?= e($m['id']) ?>" <?= $v('media_id')===(string)$m['id']?'selected':'' ?>>#<?= e($m['id']) ?> · <?= e($m['alt_text']) ?> · <?= e($m['width']) ?> × <?= e($m['height']) ?></option><?php endforeach?></select></label>
<label class="admin-field"><span>Orden</span><input type="number" name="display_order" min="0" max="65535" value="<?= e($v('display_order','0')) ?>" required></label>
<label class="admin-field"><span>Estado</span><select name="status"><?php foreach(['draft'=>'Borrador','scheduled'=>'Programado','published'=>'Publicado','archived'=>'Archivado'] as $key=>$label):if(!$canPublish&&$key!=='draft')continue;?><option value="<?= e($key) ?>" <?= $v('status','draft')===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach?></select></label>
<?php foreach(['publish_at'=>'Inicio de publicación','expires_at'=>'Fin de publicación'] as $key=>$label):$raw=$v($key);$date=preg_match('/^\d{4}-\d{2}-\d{2} /D',$raw)?(new DateTimeImmutable($raw,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('America/Hermosillo'))->format('Y-m-d\TH:i'):$raw;?><label class="admin-field"><span><?= e($label) ?> (Hermosillo)</span><input type="datetime-local" name="<?= e($key) ?>" value="<?= e($date) ?>"></label><?php endforeach?>
<?php foreach(CmsRules::FIELDS[$type] as $key=>$label):?><label class="admin-field"><span><?= e($label) ?></span><input name="fields[<?= e($key) ?>]" maxlength="250" value="<?= e($fields[$key]??'') ?>"></label><?php endforeach?></div>
<label class="admin-field"><span>Texto</span><textarea name="body" rows="8" maxlength="16000"><?= e($v('body')) ?></textarea></label><div class="admin-form-actions"><button class="admin-primary-button">Guardar revisión</button><a class="admin-secondary-button" href="/admin/cms?type=<?= e($type) ?>">Crear otro contenido</a></div></form><?php endif?>
<?php if($selected):?><section class="admin-panel"><h2>Historial de revisiones</h2><?php foreach(array_slice($revisions,0,25) as $rev):?><details><summary>Revisión <?= e($rev['version_number']) ?> · <?= e($rev['created_at']) ?> UTC · <?= e($rev['display_name']) ?></summary><pre class="cms-snapshot"><?= e(json_encode(json_decode($rev['snapshot_json'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre></details><?php endforeach?><?php if(count($revisions)>25):?><a href="/admin/cms?type=<?= e($type) ?>&amp;id=<?= e($selected['id']) ?>&amp;history_offset=<?= e($historyOffset+25) ?>">Revisiones anteriores</a><?php endif?></section><?php endif?>
